import pytest

# Test Suite for /user/login

@pytest.mark.parametrize(
    "params,expected_status",
    [
        ({"username": "validUser", "password": "validPass"}, 200),  # Valid login
        ({"username": "invalidUser", "password": "invalidPass"}, 400),  # Invalid login
        ({"username": None, "password": None}, 400),  # Missing parameters
    ]
)
def test_login_user(api_client, params, expected_status):
    """
    Test the /user/login endpoint with different combinations of query parameters.
    
    Scenarios:
    - Valid credentials (200)
    - Invalid credentials (400)
    - Missing credentials (400)
    """
    endpoint = "/user/login"
    response = api_client.get(endpoint, params=params)
    
    # Assert status code
    assert response.status_code == expected_status, \
        f"Expected {expected_status}, got {response.status_code}"
    
    if expected_status == 200:
        # Validate response headers for successful login
        assert "X-Rate-Limit" in response.headers, "Missing X-Rate-Limit header"
        assert "X-Expires-After" in response.headers, "Missing X-Expires-After header"
        
        # Validate content type and response schema
        assert response.headers["Content-Type"] in ["application/json", "application/xml"], \
            f"Unexpected response Content-Type: {response.headers['Content-Type']}"
        assert isinstance(response.json(), str), "Expected string in response body"
    
    elif expected_status == 400:
        # Validate error message for invalid login
        assert "Invalid username/password supplied" in response.text, \
            "Unexpected error message"

    elif response.status_code not in [200, 400]:
        pytest.fail("Unexpected response received!")


@pytest.mark.parametrize(
    "security_header,expected_status",
    [
        ({"Authorization": "Bearer valid_token"}, 200),  # Valid token
        ({"Authorization": "Bearer invalid_token"}, 401), # Invalid token
        (None, 403),  # Missing token
    ]
)
def test_login_security(api_client, security_header, expected_status):
    """
    Test security measures (if applicable for /user/login).
    
    Scenarios:
    - Valid tokens (200)
    - Invalid tokens (401)
    - Missing tokens (403)
    """
    endpoint = "/user/login"
    response = api_client.get(endpoint, headers=security_header)
    
    assert response.status_code == expected_status, \
        f"Expected {expected_status}, got {response.status_code}"

    if expected_status == 403:
        assert "Missing authorization token." in response.text, \
            "Unexpected error message for missing token."


